using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;
using EduSphere.Application.Interfaces;
using EduSphere.Domain.Entities;
using EduSphere.Domain.Enums;
using EduSphere.Infrastructure;
using EduSphere.Infrastructure.MultiTenancy;
using Microsoft.EntityFrameworkCore;

namespace EduSphere.Web.Services;

public sealed class TelegramNotificationSender(TenantDbContext db,IHttpClientFactory clients):INotificationChannelSender
{
 public CommunicationChannel Channel=>CommunicationChannel.Telegram;
 public async Task<NotificationDispatchResult> SendAsync(NotificationDispatchMessage m,CancellationToken ct=default){var tenantId=await db.NotificationMessages.IgnoreQueryFilters().Where(x=>x.Id==m.MessageId).Select(x=>x.TenantId).SingleAsync(ct);var s=await db.NotificationProviderSettings.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Channel==Channel&&x.IsEnabled,ct);if(s?.ConfigurationJson is null)return NotificationDispatchResult.Failure("Telegram is not configured.");using var cfg=JsonDocument.Parse(s.ConfigurationJson);if(!cfg.RootElement.TryGetProperty("botToken",out var t)||string.IsNullOrWhiteSpace(t.GetString()))return NotificationDispatchResult.Failure("Telegram botToken is missing.");var response=await clients.CreateClient().PostAsync($"https://api.telegram.org/bot{t.GetString()}/sendMessage",new FormUrlEncodedContent(new Dictionary<string,string>{{"chat_id",m.DestinationAddress},{"text",m.Body},{"parse_mode","HTML"}}),ct);var body=await response.Content.ReadAsStringAsync(ct);if(!response.IsSuccessStatusCode)return NotificationDispatchResult.Failure("Telegram rejected the message.");using var json=JsonDocument.Parse(body);var id=json.RootElement.TryGetProperty("result",out var result)&&result.TryGetProperty("message_id",out var value)?value.ToString():null;return NotificationDispatchResult.Success(id);}
}
public sealed class PushNotificationSender(TenantDbContext db,IHttpClientFactory clients):INotificationChannelSender
{
 public CommunicationChannel Channel=>CommunicationChannel.Push;
 public async Task<NotificationDispatchResult> SendAsync(NotificationDispatchMessage m,CancellationToken ct=default){if(!Guid.TryParse(m.DestinationAddress,out var userId))return NotificationDispatchResult.Failure("Push destination must be a user id.");var subscription=await db.PushSubscriptions.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x=>x.UserId==userId&&x.IsActive,ct);if(subscription?.DeviceToken is null)return NotificationDispatchResult.Failure("No active push subscription exists.");var tenantId=await db.NotificationMessages.IgnoreQueryFilters().Where(x=>x.Id==m.MessageId).Select(x=>x.TenantId).SingleAsync(ct);var setting=await db.NotificationProviderSettings.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x=>x.TenantId==tenantId&&x.Channel==Channel&&x.IsEnabled,ct);var endpoint="https://exp.host/--/api/v2/push/send";string? token=null;if(setting?.ConfigurationJson is not null){using var cfg=JsonDocument.Parse(setting.ConfigurationJson);endpoint=cfg.RootElement.TryGetProperty("endpoint",out var e)?e.GetString()??endpoint:endpoint;token=cfg.RootElement.TryGetProperty("accessToken",out var a)?a.GetString():null;}using var request=new HttpRequestMessage(HttpMethod.Post,endpoint){Content=JsonContent.Create(new{to=subscription.DeviceToken,title=m.Subject??"EduSphere",body=m.Body,data=new{messageId=m.MessageId}})};if(!string.IsNullOrWhiteSpace(token))request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);using var response=await clients.CreateClient().SendAsync(request,ct);var body=await response.Content.ReadAsStringAsync(ct);return response.IsSuccessStatusCode?NotificationDispatchResult.Success():NotificationDispatchResult.Failure($"Push provider rejected the notification: {body[..Math.Min(300,body.Length)]}");}
}
public sealed class InAppNotificationSender(TenantDbContext db):INotificationChannelSender
{
 public CommunicationChannel Channel=>CommunicationChannel.InApp;
 public async Task<NotificationDispatchResult> SendAsync(NotificationDispatchMessage m,CancellationToken ct=default){var recipient=await db.NotificationRecipients.IgnoreQueryFilters().SingleAsync(x=>x.Id==m.RecipientId,ct);var userId=recipient.UserId??(Guid.TryParse(m.DestinationAddress,out var parsed)?parsed:null);if(userId is null)return NotificationDispatchResult.Failure("In-app recipient must be linked to a user.");db.InAppNotifications.Add(new(){TenantId=recipient.TenantId,UserId=userId.Value,NotificationMessageId=m.MessageId,Title=m.Subject,Body=m.Body});await db.SaveChangesAsync(ct);return NotificationDispatchResult.Success();}
}

public sealed class CommunicationAutomationWorker(IServiceScopeFactory scopes,ILogger<CommunicationAutomationWorker> logger):BackgroundService
{
 protected override async Task ExecuteAsync(CancellationToken ct){while(!ct.IsCancellationRequested){try{await Run(ct);}catch(Exception ex){logger.LogError(ex,"Communication automation cycle failed.");}await Task.Delay(TimeSpan.FromMinutes(2),ct);}}
 private async Task Run(CancellationToken ct){using var rootScope=scopes.CreateScope();var root=rootScope.ServiceProvider.GetRequiredService<TenantDbContext>();var tenants=await root.NotificationMessages.IgnoreQueryFilters().Where(x=>!x.IsDeleted&&(x.Status==NotificationStatus.Queued||x.Status==NotificationStatus.Failed||x.ScheduledOn!=null)).Select(x=>x.TenantId).Union(root.CommunicationCampaigns.IgnoreQueryFilters().Where(x=>!x.IsDeleted&&x.Status==CampaignStatus.Scheduled).Select(x=>x.TenantId)).Distinct().ToListAsync(ct);foreach(var tenantId in tenants){using var scope=scopes.CreateScope();scope.ServiceProvider.GetRequiredService<TenantContext>().SetTenant(tenantId,tenantId.ToString());var db=scope.ServiceProvider.GetRequiredService<TenantDbContext>();var dispatcher=scope.ServiceProvider.GetRequiredService<INotificationDispatcher>();var now=DateTime.UtcNow;var campaigns=await db.CommunicationCampaigns.Where(x=>x.Status==CampaignStatus.Scheduled&&x.ScheduledOn<=now).Take(20).ToListAsync(ct);foreach(var c in campaigns){c.Status=CampaignStatus.Running;c.StartedOn=now;var users=await AudienceUsers(db,c.Audience,c.BranchId,ct);var message=new NotificationMessage{BranchId=c.BranchId,NotificationTemplateId=c.NotificationTemplateId,Channel=c.Channel,Subject=c.Subject,Body=c.Body,Status=NotificationStatus.Queued,ScheduledOn=now};foreach(var user in users){var address=c.Channel switch{CommunicationChannel.Email=>user.Email,CommunicationChannel.Sms or CommunicationChannel.WhatsApp=>user.PhoneNumber,_=>user.Id.ToString()};if(!string.IsNullOrWhiteSpace(address))message.Recipients.Add(new NotificationRecipient{BranchId=c.BranchId,UserId=user.Id,DisplayName=user.FullName,DestinationAddress=address,Status=NotificationStatus.Queued});}c.RecipientCount=message.Recipients.Count;db.NotificationMessages.Add(message);await db.SaveChangesAsync(ct);var result=await dispatcher.DispatchAsync(message.Id,ct);c.Status=result.Succeeded?CampaignStatus.Completed:CampaignStatus.Failed;c.CompletedOn=DateTime.UtcNow;c.SentCount=message.Recipients.Count(x=>x.Status==NotificationStatus.Sent);c.FailedCount=message.Recipients.Count-c.SentCount;await db.SaveChangesAsync(ct);}var due=await db.NotificationDeliveryAttempts.Where(x=>x.Status==NotificationAttemptStatus.Failed&&x.NextRetryOn<=now).GroupBy(x=>x.NotificationMessageId).Select(x=>x.Key).Take(50).ToListAsync(ct);foreach(var id in due){var attempts=await db.NotificationDeliveryAttempts.Where(x=>x.NotificationMessageId==id).CountAsync(ct);if(attempts>=5){if(!await db.NotificationDeadLetters.AnyAsync(x=>x.NotificationMessageId==id&&x.Status==DeadLetterStatus.Open,ct)){var last=await db.NotificationDeliveryAttempts.Where(x=>x.NotificationMessageId==id).OrderByDescending(x=>x.AttemptedOn).FirstAsync(ct);db.NotificationDeadLetters.Add(new(){NotificationMessageId=id,NotificationRecipientId=last.NotificationRecipientId,Channel=last.Channel,AttemptCount=attempts,LastError=last.ErrorMessage??"Delivery failed."});await db.SaveChangesAsync(ct);}continue;}await dispatcher.DispatchAsync(id,ct);}}}
 private static async Task<List<ApplicationUser>> AudienceUsers(TenantDbContext db,AnnouncementAudience audience,Guid? branchId,CancellationToken ct){var q=db.Users.AsQueryable();if(branchId.HasValue){var ids=db.UserBranchAssignments.Where(x=>x.BranchId==branchId).Select(x=>x.UserId);q=q.Where(x=>ids.Contains(x.Id));}return await q.Where(x=>x.IsActive).ToListAsync(ct);}
}
